/**
 * Calendar arithmetic for recurring issues.
 *
 * Occurrences are `YYYY-MM-DD` days in a rule's own IANA time zone, so every
 * decision here compares local calendar days rather than instants. A day has
 * started once its local midnight has passed, which is exactly "the local date
 * has reached that day", and that stays correct on daylight-saving transitions.
 */
import type { RecurrenceCadence } from "@/types/recurring-issue";

const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;
const DAY_MS = 86_400_000;

/**
 * True when `value` names a zone the runtime's Intl knows. The leading letter
 * rules out UTC offsets such as "+05:00", which Intl accepts but IANA does not.
 */
export function isKnownTimeZone(value: string): boolean {
  if (!/^[A-Za-z]/.test(value)) return false;
  try {
    new Intl.DateTimeFormat("en-US", { timeZone: value });
    return true;
  } catch {
    return false;
  }
}

/** True for a `YYYY-MM-DD` string that names a real calendar day. */
export function isCalendarDate(value: string): boolean {
  if (!DATE_PATTERN.test(value)) return false;
  const [year, month, day] = value.split("-").map(Number) as [
    number,
    number,
    number,
  ];
  // `setUTCFullYear` rather than `Date.UTC`, which maps years 0–99 onto 1900+.
  const date = new Date(0);
  date.setUTCFullYear(year, month - 1, day);
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

/** The calendar day `now` falls on in `timezone`, as `YYYY-MM-DD`. */
export function localDateOn(now: Date, timezone: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: timezone,
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
  }).formatToParts(now);
  const part = (type: "year" | "month" | "day") =>
    parts.find((candidate) => candidate.type === type)?.value ?? "";
  return `${part("year")}-${part("month")}-${part("day")}`;
}

/** ISO weekday of a `YYYY-MM-DD` day: 1 = Monday … 7 = Sunday. */
export function isoWeekdayOf(date: string): number {
  const sundayBased = new Date(`${date}T00:00:00Z`).getUTCDay();
  return sundayBased === 0 ? 7 : sundayBased;
}

/** `date` moved by `days` calendar days (negative goes back). */
export function shiftDate(date: string, days: number): string {
  const shifted = new Date(Date.parse(`${date}T00:00:00Z`) + days * DAY_MS);
  return shifted.toISOString().slice(0, 10);
}

export interface OccurrenceSchedule {
  readonly cadence: RecurrenceCadence;
  readonly weekday: number | null;
  readonly timezone: string;
  readonly startsOn: string;
}

/**
 * The latest occurrence day of `schedule` that has started by `now`, or `null`
 * when none has. Daily rules occur on today's local date; weekly rules on the
 * most recent day, today included, whose ISO weekday matches. Either way the
 * day must be on or after `startsOn`.
 */
export function latestStartedOccurrence(
  schedule: OccurrenceSchedule,
  now: Date,
): string | null {
  const today = localDateOn(now, schedule.timezone);

  let latest: string;
  if (schedule.cadence === "daily") {
    latest = today;
  } else {
    if (schedule.weekday === null) return null;
    const daysBack = (isoWeekdayOf(today) - schedule.weekday + 7) % 7;
    latest = shiftDate(today, -daysBack);
  }

  return latest >= schedule.startsOn ? latest : null;
}

