import { PermissionDeniedError } from "@/lib/permissions";
import { isArchived } from "@/lib/soft-delete";
import * as memberRepo from "@/server/repositories/member-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import { createIssue } from "@/server/services/issue-service";
import type { UserId } from "@/types/common";
import type { Actor } from "@/types/member";
import type { RecurringIssue } from "@/types/recurring-issue";
import { runJob } from "./types";
import type { JobResult } from "./types";

const logger = createLogger("recurring-issue-job");

type Outcome = "filed" | "skipped" | "paused";

/**
 * Processes one rule. Nothing is filed unless the latest started occurrence is
 * newer than `lastOccurrenceOn`; a rule whose project is archived is left alone;
 * a creator who has left or lost issue-create rights pauses the rule. Any other
 * refusal throws, so the rule keeps its state and the next run retries it.
 */
async function fileOccurrence(
  rule: RecurringIssue,
  now: Date,
): Promise<Outcome> {
  const occurrence = latestStartedOccurrence(rule, now);
  if (occurrence === null) return "skipped";
  if (rule.lastOccurrenceOn !== null && occurrence <= rule.lastOccurrenceOn) {
    return "skipped";
  }

  const project = await projectRepo.findProjectById(rule.orgId, rule.projectId);
  if (project === null) {
    throw new Error(`Project ${rule.projectId} was not found`);
  }
  if (isArchived(project)) return "skipped";

  const creator = await memberRepo.findMember(rule.orgId, rule.createdBy);
  if (creator === null || creator.status !== "active") {
    return pause(rule, "creator is no longer an active member");
  }

  const actor: Actor = {
    userId: rule.createdBy,
    orgId: rule.orgId,
    role: creator.role,
  };

  try {
    await createIssue(actor, {
      orgId: rule.orgId,
      projectId: rule.projectId,
      title: `${rule.title} (${occurrence})`,
      description: null,
      status: "backlog",
      priority: rule.priority,
      assigneeId: await activeAssigneeId(rule),
      parentId: null,
      estimate: null,
      dueAt: null,
      labelIds: [],
    });
  } catch (error) {
    if (error instanceof PermissionDeniedError) {
      return pause(rule, "creator may no longer create issues in this project");
    }
    throw error;
  }

  await recurringIssueRepo.updateRecurringIssue(rule.orgId, rule.id, {
    lastOccurrenceOn: occurrence,
  });
  return "filed";
}

async function pause(rule: RecurringIssue, reason: string): Promise<Outcome> {
  await recurringIssueRepo.updateRecurringIssue(rule.orgId, rule.id, {
    paused: true,
  });
  logger.warn("recurring issue paused", { recurringIssueId: rule.id, reason });
  return "paused";
}

/** The rule's assignee while they remain an active member; otherwise nobody. */
async function activeAssigneeId(rule: RecurringIssue): Promise<UserId | null> {
  if (rule.assigneeId === null) return null;
  const assignee = await memberRepo.findMember(rule.orgId, rule.assigneeId);
  return assignee !== null && assignee.status === "active"
    ? rule.assigneeId
    : null;
}

/**
 * Sweeps every non-paused rule. One rule's failure is counted and logged, and
 * never stops the rest; `processed` counts the issues actually created.
 */
export async function runRecurringIssueJob(now: Date): Promise<JobResult> {
  return runJob("recurring-issues", async (result) => {
    const rules = await recurringIssueRepo.listActiveRecurringIssues();

    for (const rule of rules) {
      try {
        if ((await fileOccurrence(rule, now)) === "filed") {
          result.processed += 1;
        }
      } catch (error) {
        result.failed += 1;
        logger.error("failed to file recurring issue", {
          recurringIssueId: rule.id,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}

