  orgId: ORG_A,
  projectId: PROJECT_ID,
  title: "Daily triage",
  cadence: "daily" as const,
  weekday: null,
  timezone: "UTC",
  startsOn: "2026-03-01",
};

describe("latestStartedOccurrence", () => {
  const daily = { cadence: "daily" as const, weekday: null, timezone: "UTC", startsOn: "2026-03-01" };

  it("daily: today's local date once it has begun", () => {
    expect(latestStartedOccurrence(daily, new Date("2026-03-05T00:00:00Z"))).toBe("2026-03-05");
    expect(latestStartedOccurrence(daily, new Date("2026-03-05T23:59:59Z"))).toBe("2026-03-05");
  });

  it("nothing before startsOn", () => {
    expect(latestStartedOccurrence(daily, new Date("2026-02-28T12:00:00Z"))).toBeNull();
    expect(latestStartedOccurrence({ ...daily, startsOn: "2026-03-01" }, new Date("2026-03-01T00:00:00Z"))).toBe("2026-03-01");
  });

  it("weekly: most recent matching ISO weekday, today included", () => {
    // 2026-03-05 is a Thursday (ISO 4).
    const weekly = (weekday: number) => ({ cadence: "weekly" as const, weekday, timezone: "UTC", startsOn: "2026-03-01" });
    const thu = new Date("2026-03-05T12:00:00Z");
    expect(latestStartedOccurrence(weekly(4), thu)).toBe("2026-03-05");
    expect(latestStartedOccurrence(weekly(1), thu)).toBe("2026-03-02");
    expect(latestStartedOccurrence(weekly(5), thu)).toBe("2026-02-27".length && null);
    expect(latestStartedOccurrence(weekly(7), thu)).toBe("2026-03-01");
  });

  it("weekly before the first matching day on/after startsOn is null", () => {
    // startsOn is a Wednesday; the Monday before it is not an occurrence.
    const rule = { cadence: "weekly" as const, weekday: 1, timezone: "UTC", startsOn: "2026-03-04" };
    expect(latestStartedOccurrence(rule, new Date("2026-03-05T12:00:00Z"))).toBeNull();
    expect(latestStartedOccurrence(rule, new Date("2026-03-09T12:00:00Z"))).toBe("2026-03-09");
  });

  it("uses the rule's own time zone for the calendar day", () => {
    const now = new Date("2026-03-04T16:30:00Z"); // 01:30 on the 5th in Tokyo
    expect(latestStartedOccurrence({ ...daily, timezone: "Asia/Tokyo" }, now)).toBe("2026-03-05");
    expect(latestStartedOccurrence({ ...daily, timezone: "UTC" }, now)).toBe("2026-03-04");
  });

  it("handles the New York spring-forward day", () => {
    // DST starts 2026-03-08 at 02:00 EST (07:00Z).
    expect(latestStartedOccurrence({ ...daily, timezone: "America/New_York" }, new Date("2026-03-08T04:30:00Z"))).toBe("2026-03-07");
    expect(latestStartedOccurrence({ ...daily, timezone: "America/New_York" }, new Date("2026-03-08T07:30:00Z"))).toBe("2026-03-08");
  });
});

