import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { eq } from "drizzle-orm";
import { latestStartedOccurrence } from "@/lib/recurrence";
import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import { createRecurringIssueSchema } from "@/schemas/recurring-issue";
import { getDb, issues, members, projects } from "@/server/db";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as recurringIssueRepo from "@/server/repositories/recurring-issue-repository";
import * as recurringIssueService from "@/server/services/recurring-issue-service";
import { runRecurringIssueJob } from "@/server/jobs/recurring-issue-job";
import { ORG_A } from "../helpers/factories";
import { createTenant, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";

const PROJECT_ID = "01HZZZCCCCCCCCCCCCCCCCCCCC";
const base = {
  orgId: ORG_A,
  projectId: PROJECT_ID,
  title: "Daily triage",
  cadence: "daily" as const,
  weekday: null,
  timezone: "UTC",
  startsOn: "2026-03-01",
};

describe("latestStartedOccurrence", () => {
  const daily = { cadence: "daily" as const, weekday: null, timezone: "UTC", startsOn: "2026-03-01" };

  it("daily: today's local date once it has begun", () => {
    expect(latestStartedOccurrence(daily, new Date("2026-03-05T00:00:00Z"))).toBe("2026-03-05");
    expect(latestStartedOccurrence(daily, new Date("2026-03-05T23:59:59Z"))).toBe("2026-03-05");
  });

  it("nothing before startsOn", () => {
    expect(latestStartedOccurrence(daily, new Date("2026-02-28T12:00:00Z"))).toBeNull();
    expect(latestStartedOccurrence({ ...daily, startsOn: "2026-03-01" }, new Date("2026-03-01T00:00:00Z"))).toBe("2026-03-01");
  });

  it("weekly: most recent matching ISO weekday, today included", () => {
    // 2026-03-05 is a Thursday (ISO 4).
    const weekly = (weekday: number) => ({ cadence: "weekly" as const, weekday, timezone: "UTC", startsOn: "2026-03-01" });
    const thu = new Date("2026-03-05T12:00:00Z");
    expect(latestStartedOccurrence(weekly(4), thu)).toBe("2026-03-05");
    expect(latestStartedOccurrence(weekly(1), thu)).toBe("2026-03-02");
    expect(latestStartedOccurrence(weekly(5), thu)).toBe("2026-02-27".length && null);
    expect(latestStartedOccurrence(weekly(7), thu)).toBe("2026-03-01");
  });

  it("weekly before the first matching day on/after startsOn is null", () => {
    // startsOn is a Wednesday; the Monday before it is not an occurrence.
    const rule = { cadence: "weekly" as const, weekday: 1, timezone: "UTC", startsOn: "2026-03-04" };
    expect(latestStartedOccurrence(rule, new Date("2026-03-05T12:00:00Z"))).toBeNull();
    expect(latestStartedOccurrence(rule, new Date("2026-03-09T12:00:00Z"))).toBe("2026-03-09");
  });

  it("uses the rule's own time zone for the calendar day", () => {
    const now = new Date("2026-03-04T16:30:00Z"); // 01:30 on the 5th in Tokyo
    expect(latestStartedOccurrence({ ...daily, timezone: "Asia/Tokyo" }, now)).toBe("2026-03-05");
    expect(latestStartedOccurrence({ ...daily, timezone: "UTC" }, now)).toBe("2026-03-04");
  });

  it("handles the New York spring-forward day", () => {
    // DST starts 2026-03-08 at 02:00 EST (07:00Z).
    expect(latestStartedOccurrence({ ...daily, timezone: "America/New_York" }, new Date("2026-03-08T04:30:00Z"))).toBe("2026-03-07");
    expect(latestStartedOccurrence({ ...daily, timezone: "America/New_York" }, new Date("2026-03-08T07:30:00Z"))).toBe("2026-03-08");
  });
});

describe("createRecurringIssueSchema", () => {
  it("accepts a valid daily rule and applies defaults", () => {
    const parsed = createRecurringIssueSchema.parse(base);
    expect(parsed.priority).toBe("none");
    expect(parsed.assigneeId).toBeNull();
    expect(parsed.weekday).toBeNull();
  });

  it("rejects cadence/weekday mismatches", () => {
    expect(createRecurringIssueSchema.safeParse({ ...base, cadence: "weekly", weekday: null }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, cadence: "daily", weekday: 1 }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, cadence: "weekly", weekday: 7 }).success).toBe(true);
  });

  it("rejects unknown time zones and non-IANA offsets", () => {
    expect(createRecurringIssueSchema.safeParse({ ...base, timezone: "Mars/Olympus" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, timezone: "+05:00" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, timezone: "Europe/Berlin" }).success).toBe(true);
  });

  it("rejects impossible calendar dates and bad shapes", () => {
    expect(createRecurringIssueSchema.safeParse({ ...base, startsOn: "2026-02-30" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, startsOn: "2024-02-29" }).success).toBe(true);
    expect(createRecurringIssueSchema.safeParse({ ...base, startsOn: "2026-3-5" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, title: "ab" }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, title: "x".repeat(181) }).success).toBe(false);
    expect(createRecurringIssueSchema.safeParse({ ...base, cadence: "weekly", weekday: 8 }).success).toBe(false);
  });
});

describe("recurring issue service and job", () => {
  let cleanup: () => void;
  let tenant: Tenant;
  let other: Tenant;

  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
    tenant = await createTenant("recur");
    other = await createTenant("recurb");
  });

  afterAll(() => cleanup());

  const input = (over: Record<string, unknown> = {}) => ({
    orgId: tenant.org.id,
    projectId: tenant.project.id,
    title: "Daily triage",
    cadence: "daily" as const,
    weekday: null,
    timezone: "UTC",
    startsOn: "2026-03-01",
    ...over,
  });

  it("creates a rule owned by the actor, unpaused and never filed", async () => {
    const rule = await recurringIssueService.createRecurringIssue(tenant.actors.member, input());
    expect(rule).toMatchObject({ lastOccurrenceOn: null, paused: false, createdBy: tenant.userIds.member, priority: "none", assigneeId: null });
  });

  it("refuses viewers, other tenants, unknown assignees and free-plan creation", async () => {
    await expect(recurringIssueService.createRecurringIssue(tenant.actors.viewer, input())).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(recurringIssueService.createRecurringIssue(tenant.actors.member, input({ orgId: other.org.id, projectId: other.project.id }))).rejects.toBeInstanceOf(TenantScopeError);
    await expect(recurringIssueService.createRecurringIssue(tenant.actors.member, input({ assigneeId: "01HZZZDDDDDDDDDDDDDDDDDDDD" }))).rejects.toThrow();
    const free = await createTenant("recurfree", "free");
    await expect(
      recurringIssueService.createRecurringIssue(free.actors.member, { ...input(), orgId: free.org.id, projectId: free.project.id }),
    ).rejects.toThrow();
  });

  it("lists in creation order and pauses via the service", async () => {
    const all = await recurringIssueService.listRecurringIssues(tenant.actors.viewer, tenant.org.id);
    expect(all.length).toBeGreaterThanOrEqual(1);
    await expect(recurringIssueService.listRecurringIssues(tenant.actors.viewer, other.org.id)).rejects.toBeInstanceOf(TenantScopeError);
    const paused = await recurringIssueService.setRecurringIssuePaused(tenant.actors.member, {
      orgId: tenant.org.id,
      recurringIssueId: all[0].id,
      paused: true,
    });
    expect(paused.paused).toBe(true);
    await expect(
      recurringIssueService.setRecurringIssuePaused(tenant.actors.member, { orgId: tenant.org.id, recurringIssueId: "01HZZZDDDDDDDDDDDDDDDDDDDD", paused: true }),
    ).rejects.toThrow(/not found/);
    await recurringIssueService.setRecurringIssuePaused(tenant.actors.member, { orgId: tenant.org.id, recurringIssueId: all[0].id, paused: false });
  });

  it("files the latest occurrence once, without back-filling", async () => {
    const rule = await recurringIssueService.createRecurringIssue(tenant.actors.member, input({ title: "Standup" }));
    const now = new Date("2026-03-05T12:00:00Z");
    await runRecurringIssueJob(now);
    const after = await recurringIssueRepo.findRecurringIssueById(tenant.org.id, rule.id);
    expect(after?.lastOccurrenceOn).toBe("2026-03-05");
    const filed = getDb().select().from(issues).where(eq(issues.projectId, tenant.project.id)).all().filter((row) => row.title === "Standup (2026-03-05)");
    expect(filed).toHaveLength(1);
    expect(filed[0]).toMatchObject({ status: "backlog", priority: "none", assigneeId: null, authorId: tenant.userIds.member, description: null, dueAt: null });

    await runRecurringIssueJob(now);
    expect(await issueRepo.countIssues(tenant.org.id, tenant.project.id)).toBe(
      getDb().select().from(issues).where(eq(issues.projectId, tenant.project.id)).all().length,
    );
    const titles = getDb().select().from(issues).where(eq(issues.projectId, tenant.project.id)).all().map((row) => row.title);
    expect(titles.filter((title) => title === "Standup (2026-03-05)")).toHaveLength(1);

    // Ten days later the job files only the new latest day, not every missed one.
    await runRecurringIssueJob(new Date("2026-03-15T12:00:00Z"));
    const later = getDb().select().from(issues).where(eq(issues.projectId, tenant.project.id)).all().map((row) => row.title);
    expect(later.filter((title) => title.startsWith("Standup ("))).toEqual(["Standup (2026-03-05)", "Standup (2026-03-15)"]);
  });

  it("skips archived projects and resumes once restored", async () => {
    const archived = await createTenant("recurarch");
    const rule = await recurringIssueService.createRecurringIssue(archived.actors.member, {
      orgId: archived.org.id,
      projectId: archived.project.id,
      title: "Weekly planning",
      cadence: "weekly",
      weekday: 1,
      timezone: "UTC",
      startsOn: "2026-03-01",
    });
    getDb().update(projects).set({ archivedAt: new Date().toISOString() }).where(eq(projects.id, archived.project.id)).run();
    await runRecurringIssueJob(new Date("2026-03-05T12:00:00Z"));
    expect((await recurringIssueRepo.findRecurringIssueById(archived.org.id, rule.id))).toMatchObject({ lastOccurrenceOn: null, paused: false });

    getDb().update(projects).set({ archivedAt: null }).where(eq(projects.id, archived.project.id)).run();
    await runRecurringIssueJob(new Date("2026-03-05T12:00:00Z"));
    expect((await recurringIssueRepo.findRecurringIssueById(archived.org.id, rule.id))?.lastOccurrenceOn).toBe("2026-03-02");
    const titles = getDb().select().from(issues).where(eq(issues.projectId, archived.project.id)).all().map((row) => row.title);
    expect(titles).toEqual(["Weekly planning (2026-03-02)"]);
  });

  it("pauses when the creator is gone or can no longer create issues", async () => {
    const gone = await createTenant("recurgone");
    const demoted = await createTenant("recurdemote");
    const goneRule = await recurringIssueService.createRecurringIssue(gone.actors.member, { ...input(), orgId: gone.org.id, projectId: gone.project.id });
    const demotedRule = await recurringIssueService.createRecurringIssue(demoted.actors.member, { ...input(), orgId: demoted.org.id, projectId: demoted.project.id });

    getDb().update(members).set({ status: "suspended" }).where(eq(members.userId, gone.userIds.member)).run();
    getDb().update(members).set({ role: "viewer" }).where(eq(members.userId, demoted.userIds.member)).run();
    await runRecurringIssueJob(new Date("2026-03-05T12:00:00Z"));

    expect((await recurringIssueRepo.findRecurringIssueById(gone.org.id, goneRule.id))).toMatchObject({ paused: true, lastOccurrenceOn: null });
    expect((await recurringIssueRepo.findRecurringIssueById(demoted.org.id, demotedRule.id))).toMatchObject({ paused: true, lastOccurrenceOn: null });
    expect(await issueRepo.countIssues(gone.org.id, gone.project.id)).toBe(0);
    expect(await issueRepo.countIssues(demoted.org.id, demoted.project.id)).toBe(0);
  });

  it("files unassigned when the assignee has left, and keeps the assignee otherwise", async () => {
    const assignee = await createTenant("recurassign");
    const kept = await recurringIssueService.createRecurringIssue(assignee.actors.member, { ...input(), orgId: assignee.org.id, projectId: assignee.project.id, title: "Kept", assigneeId: assignee.userIds.admin });
    const dropped = await recurringIssueService.createRecurringIssue(assignee.actors.member, { ...input(), orgId: assignee.org.id, projectId: assignee.project.id, title: "Dropped", assigneeId: assignee.userIds.viewer });
    getDb().update(members).set({ status: "suspended" }).where(eq(members.userId, assignee.userIds.viewer)).run();
    await runRecurringIssueJob(new Date("2026-03-05T12:00:00Z"));
    const rows = getDb().select().from(issues).where(eq(issues.projectId, assignee.project.id)).all();
    expect(rows.find((row) => row.title === "Kept (2026-03-05)")?.assigneeId).toBe(assignee.userIds.admin);
    expect(rows.find((row) => row.title === "Dropped (2026-03-05)")?.assigneeId).toBeNull();
    expect((await recurringIssueRepo.findRecurringIssueById(assignee.org.id, kept.id))?.lastOccurrenceOn).toBe("2026-03-05");
    expect((await recurringIssueRepo.findRecurringIssueById(assignee.org.id, dropped.id))?.lastOccurrenceOn).toBe("2026-03-05");
  });

  it("refuses an over-quota create and leaves the rule untouched when the issue quota refuses", async () => {
    const full = await createTenant("recurquota", "starter");
    for (let i = 0; i < 3; i += 1) {
      await recurringIssueService.createRecurringIssue(full.actors.member, { ...input(), orgId: full.org.id, projectId: full.project.id, title: `Rule ${i}` });
    }
    await expect(
      recurringIssueService.createRecurringIssue(full.actors.member, { ...input(), orgId: full.org.id, projectId: full.project.id, title: "Rule 4" }),
    ).rejects.toThrow();
    expect(await recurringIssueRepo.countRecurringIssues(full.org.id)).toBe(3);
  });
});
